mapper.select:
select T.PROD_ID prodId, nvl(rpi2.PROD_NAME,rpi1.PROD_NAME || '(' || rpi.PROD_NAME || ')') prodName, T.VALUE_DATE valueDate, T.ASSETS_VALUE assetsValue, T.CAPITAL capital, T.UNIT_VALUE unitValue, T.UNIT_VALUE_T unitValueT, T.W_YIELD wYield, T.YIELD_7 yield7, T.STATUS status, rpi.P_PROD_ID pProdId, T2.P_ASSETS pAssets, T2.ASSETS_VALUE pAssetsValue, T2.CAPITAL pCapital, T2.UNIT_VALUE pUnitValue, T2.UNIT_VALUE_T pUnitValueT, T2.W_YIELD pWYield, T2.YIELD_7 pYield7, T.UPDATE_USER updateUser, T.UPDATE_TIME updateTime, T.ERRORMSG errormsg from REP_PROD_INDEX T left join REP_PROD_INFO rpi on T.PROD_ID = rpi.PROD_ID left join REP_PROD_INDEX T2 on rpi.P_PROD_ID = T2.PROD_ID and T.VALUE_DATE = T2.VALUE_DATE left join REP_PROD_INFO rpi1 on rpi.P_PROD_ID = rpi1.PROD_ID and rpi1.REP_PROD_TYPE = '01' left join REP_PROD_INFO rpi2 on rpi.PROD_ID = rpi2.PROD_ID and rpi2.REP_PROD_TYPE = '02' where rpi.P_PROD_ID is not null
#{item,jdbcType=VARCHAR}
and T.VALUE_DATE >= to_date(#{startDate,jdbcType=DATE},'yyyy-MM-dd')
and T.VALUE_DATE <= to_date(#{endDate,jdbcType=DATE},'yyyy-MM-dd')
and T.STATUS = #{status,jdbcType=VARCHAR}

mapper.delete:
		update REP_PROD_INDEX
		set STATUS = 'D',
            UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
            UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
		where PROD_ID = #{prodId,jdbcType=VARCHAR}
          and VALUE_DATE = #{valueDate,jdbcType=DATE}

		update REP_PROD_INDEX
		set STATUS = 'D',
            UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
            UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
		where PROD_ID = #{pProdId,jdbcType=VARCHAR}
          and VALUE_DATE = #{valueDate,jdbcType=DATE}

