where T1.PROD_ID = #{pProdId,jdbcType=VARCHAR}
and T1.VALUE_DATE = #{valueDate,jdbcType=DATE}
and T1.P_ASSETS = #{pAssets,jdbcType=DECIMAL}
and T1.ASSETS_VALUE = #{pAssetsValue,jdbcType=DECIMAL}
and T1.CAPITAL = #{pCapital,jdbcType=DECIMAL}
and T1.UNIT_VALUE = #{pUnitValue,jdbcType=DECIMAL}
and T1.UNIT_VALUE_T = #{pUnitValueT,jdbcType=DECIMAL}

    and T1.W_YIELD = #{pWYield,jdbcType=DECIMAL}


    and T1.W_YIELD is null


    and T1.YIELD_7 = #{pYield7,jdbcType=DECIMAL}


    and T1.YIELD_7 is null

and T1.STATUS != 'D'

SELECT T1.*
from REP_PROD_INDEX T1
where T1.PROD_ID = #{pProdId,jdbcType=VARCHAR}
and T1.VALUE_DATE = #{valueDate,jdbcType=DATE}
and T1.STATUS != 'D'

select distinct T.*
from REP_PROD_INDEX T
where T.PROD_ID = #{prodId,jdbcType=VARCHAR}
  and T.VALUE_DATE = #{valueDate,jdbcType=DATE}
  and T.STATUS = 'D'
